// Cosmos DB context demonstrating EF Core 9 breaking-change fixes
class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=dummy",
            "CatalogDb");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // BREAKING CHANGE 1: EF Core 9 Cosmos provider renamed the
        // discriminator property from "Discriminator" to "$type".
        // Fix: explicitly configure the old property name to remain
        // compatible with existing documents.
        modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");

        modelBuilder.Entity<Product>().ToContainer("Products");
    }

    // BREAKING CHANGE 2: Synchronous I/O on Cosmos DB now throws by default.
    // Fix: use async methods (ToListAsync, FirstOrDefaultAsync, etc.)
    public async Task<List<Product>> GetProductsAsync()
        => await Products.ToListAsync();
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
}

